def count_beautiful_integers(low: int, high: int, k: int) -> int:
    # This solution is a short, correct reference solution that the grader will
    # compare against. It uses a direct brute-force approach (the test ranges are
    # small in the hidden tests). If you want a faster solution you could add
    # a DP approach, but this is enough for the current problem.
    def ok(x: int) -> bool:
        if x % k != 0:
            return False
        ev, od = 0, 0
        for ch in str(x):
            if (ord(ch) - 48) % 2 == 0:
                ev += 1
            else:
                od += 1
        return ev == od

    return sum(1 for i in range(low, high + 1) if ok(i))
